// Measure the default avatar geometry (Profile avatar circle, camera badge disc, Home tab-bar avatar).
// Measurement only: writes nothing. Numbers are recorded in docs/ui-measurements.md §5 and §7.
// (The asset itself is generated by avatar-v2.ts.)


import { PNG } from 'pngjs';
import { loadPng, px, dist, hex, type RGB } from './lib.ts';

const prof = loadPng('07-profile.png');
const home = loadPng('04-home.png');

/** Fit a circle (Kasa least squares) to boundary points where pixels stop matching the background colour. */
function fitCircle(img: PNG, cx0: number, cy0: number, rGuess: number, bg: RGB, angles: number[]) {
  const pts: [number, number][] = [];
  for (const a of angles) {
    const dx = Math.cos(a), dy = Math.sin(a);
    // walk inward from outside the circle; first pixel that is clearly not background
    for (let t = rGuess + 12; t > rGuess - 25; t -= 0.25) {
      const x = Math.round(cx0 + dx * t), y = Math.round(cy0 + dy * t);
      if (dist(px(img, x, y), bg) > 25) { pts.push([cx0 + dx * t, cy0 + dy * t]); break; }
    }
  }
  let Sxx = 0, Sxy = 0, Syy = 0, Sx = 0, Sy = 0, n = 0, Sxz = 0, Syz = 0, Sz = 0;
  for (const [x, y] of pts) { const z = x * x + y * y; Sxx += x * x; Sxy += x * y; Syy += y * y; Sx += x; Sy += y; n++; Sxz += x * z; Syz += y * z; Sz += z; }
  const A = [[Sxx, Sxy, Sx], [Sxy, Syy, Sy], [Sx, Sy, n]], b = [-Sxz, -Syz, -Sz];
  const det = (m: number[][]) => m[0][0] * (m[1][1] * m[2][2] - m[1][2] * m[2][1]) - m[0][1] * (m[1][0] * m[2][2] - m[1][2] * m[2][0]) + m[0][2] * (m[1][0] * m[2][1] - m[1][1] * m[2][0]);
  const d0 = det(A); const s = [0, 1, 2].map((i) => det(A.map((r, ri) => r.map((v, ci) => (ci === i ? b[ri] : v)))) / d0);
  const cx = -s[0] / 2, cy = -s[1] / 2; return { cx, cy, r: Math.sqrt(cx * cx + cy * cy - s[2]), n: pts.length };
}
const deg = (a: number, b: number, step = 3) => { const o: number[] = []; for (let d = a; d <= b; d += step) o.push((d * Math.PI) / 180); return o; };

// --- profile avatar: card background around it; use the arc that the badge does not touch (90°..360° clockwise from +x excludes bottom-right)
const cardBg = px(prof, 80, 433);
const P = fitCircle(prof, 207, 433, 99, cardBg, deg(110, 370));
// --- badge: blue disc + dark ring. Fit the blue disc, ring is card-coloured
const badgeBlue: RGB = px(prof, 279, 520);
const Bd = fitCircle(prof, 279, 506, 33, cardBg, deg(-40, 120)); // outer edge of the badge disc against the card (lower-right side)
// ring thickness: walk from badge centre toward the avatar centre and find where avatar pixels resume
// ring = card-coloured gap between the blue disc and the avatar (probed: blue to ~33, card 35-38, avatar from ~39 device px)
const ring = 39 - Bd.r;
// --- home tab avatar (inactive: no ring)
const tabBg = px(home, 860, 2220);
const T0 = fitCircle(home, 927, 2220, 35, tabBg, deg(0, 357, 4));
// the inactive tab avatar has a 1 CSS px #3F424B border: artwork starts ~3.5 device px inside
const T = { ...T0, r: T0.r - 3.5 };
console.log(`profile avatar: centre ${P.cx.toFixed(2)},${P.cy.toFixed(2)} r ${P.r.toFixed(2)} (${P.n} pts)  => CSS diameter ${(2 * P.r / 3).toFixed(2)}px; card bg ${hex(cardBg)}`);
// Camera badge geometry is measured precisely by badge.ts (docs §6); the rough badge fit above only locates the occluded region.
console.log(`tab avatar:    centre ${T.cx.toFixed(2)},${T.cy.toFixed(2)} r ${T.r.toFixed(2)} => CSS diameter ${(2 * T.r / 3).toFixed(2)}px; bg ${hex(tabBg)}`);
